def game_score(points: str) -> str:
    a_points = 0
    b_points = 0

    for point in points:
        # If someone has already won, ignore remaining points
        if a_points >= 4 or b_points >= 4:
            break

        if point == 'A':
            a_points += 1
        else:  # point == 'B'
            b_points += 1

        # Check for game win
        if a_points >= 4 and a_points > b_points:
            return "Game A"
        if b_points >= 4 and b_points > a_points:
            return "Game B"

    # Convert points to tennis scoring (0, 15, 30, 40)
    score_map = {0: '0', 1: '15', 2: '30', 3: '40'}

    a_score = score_map[min(a_points, 3)]
    b_score = score_map[min(b_points, 3)]

    return f"{a_score}-{b_score}"
